                new TaskCreateRequest(key(), "T-2", "G", "下游任务", List.of("INC-A")));
        // 合成任务需 PHOTO 与 READING
        service.configureEvidenceRequirements("INC-A", "T-1", "alice",
                new EvidenceConfigRequest(key(), 1L, List.of("PHOTO", "READING")));
